from pathlib import Path


def replace_one(path: str, old: str, new: str) -> None:
    p = Path(path)
    s = p.read_text()
    count = s.count(old)
    assert count == 1, (path, count, old[:160])
    p.write_text(s.replace(old, new, 1))


# Generic nested function-pointer member annotation, previously proved on DRM
# and CUDA. A callback-bearing input record is copied on the guest stack;
# callback fields receive partial host trampolines there and are finalized by
# generated host code after ordinary record repacking.
replace_one(
    'ThunkLibs/include/common/GeneratorInterface.h',
    'struct custom_repack {};\n',
    '''struct custom_repack {};\n\n// Research prototype: mark a function-pointer structure member as a guest\n// callback. callback_member conversion is generated by thunkgen.\nstruct callback_member {};\n''')

replace_one(
    'ThunkLibs/Generator/analysis.h',
    '''    // Set of members (identified by their field name) with custom repacking\n    std::unordered_set<std::string> custom_repacked_members;\n\n    bool UsesCustomRepackFor(const clang::FieldDecl* member) const {\n      return custom_repacked_members.contains(member->getNameAsString());\n    }\n    bool UsesCustomRepackFor(const std::string& member_name) const {\n      return custom_repacked_members.contains(member_name);\n    }\n''',
    '''    // Set of members (identified by their field name) with custom repacking.\n    // callback_members are included here because automatic layout conversion\n    // must leave their raw function-pointer values for callback-specific code.\n    std::unordered_set<std::string> custom_repacked_members;\n    std::unordered_set<std::string> callback_members;\n\n    bool UsesCustomRepackFor(const clang::FieldDecl* member) const {\n      return custom_repacked_members.contains(member->getNameAsString());\n    }\n    bool UsesCustomRepackFor(const std::string& member_name) const {\n      return custom_repacked_members.contains(member_name);\n    }\n    bool UsesCallbackMemberFor(const clang::FieldDecl* member) const {\n      return callback_members.contains(member->getNameAsString());\n    }\n    bool HasManualCustomRepack() const {\n      for (const auto& member : custom_repacked_members) {\n        if (!callback_members.contains(member)) {\n          return true;\n        }\n      }\n      return false;\n    }\n''')

replace_one(
    'ThunkLibs/Generator/analysis.cpp',
    '''        } else if (auto annotated_member = llvm::dyn_cast<clang::FieldDecl>(template_args[0].getAsDecl())) {\n          if (decl->getNumBases() != 1 || decl->bases_begin()->getType().getAsString() != "fexgen::custom_repack") {\n            throw report_error(template_arg_loc, "Unsupported member annotation(s)");\n          }\n\n          // Get or add parent type to list of structure types\n#if CLANG_VERSION_MAJOR >= 22\n          auto parent_qt = context.getTagType(clang::ElaboratedTypeKeyword::None, std::nullopt, annotated_member->getParent(), false);\n          auto repack_info_it = types.emplace(context.getCanonicalType(parent_qt).getTypePtr(), RepackedType {}).first;\n#else\n          auto repack_info_it = types.emplace(context.getCanonicalType(annotated_member->getParent()->getTypeForDecl()), RepackedType {}).first;\n#endif\n          if (repack_info_it->second.assumed_compatible) {\n            throw report_error(template_arg_loc, "May not annotate members of opaque types");\n          }\n          // Add member to its list of members\n          repack_info_it->second.custom_repacked_members.insert(annotated_member->getNameAsString());\n''',
    '''        } else if (auto annotated_member = llvm::dyn_cast<clang::FieldDecl>(template_args[0].getAsDecl())) {\n          if (decl->getNumBases() != 1) {\n            throw report_error(template_arg_loc, "Unsupported member annotation(s)");\n          }\n          auto member_annotation = decl->bases_begin()->getType().getAsString();\n          if (member_annotation != "fexgen::custom_repack" && member_annotation != "fexgen::callback_member") {\n            throw report_error(template_arg_loc, "Unsupported member annotation(s)");\n          }\n\n          // Get or add parent type to list of structure types\n#if CLANG_VERSION_MAJOR >= 22\n          auto parent_qt = context.getTagType(clang::ElaboratedTypeKeyword::None, std::nullopt, annotated_member->getParent(), false);\n          auto repack_info_it = types.emplace(context.getCanonicalType(parent_qt).getTypePtr(), RepackedType {}).first;\n#else\n          auto repack_info_it = types.emplace(context.getCanonicalType(annotated_member->getParent()->getTypeForDecl()), RepackedType {}).first;\n#endif\n          if (repack_info_it->second.assumed_compatible) {\n            throw report_error(template_arg_loc, "May not annotate members of opaque types");\n          }\n\n          auto member_name = annotated_member->getNameAsString();\n          repack_info_it->second.custom_repacked_members.insert(member_name);\n\n          if (member_annotation == "fexgen::callback_member") {\n            if (!annotated_member->getType()->isFunctionPointerType()) {\n              throw report_error(template_arg_loc, "callback_member requires a function-pointer field");\n            }\n            auto funcptr = annotated_member->getType()->getPointeeType()->getAs<clang::FunctionProtoType>();\n            if (!funcptr) {\n              throw report_error(template_arg_loc, "callback_member requires a prototype function-pointer field");\n            }\n            if (funcptr->isVariadic()) {\n              throw report_error(template_arg_loc, "Variadic callback members are not supported by this prototype");\n            }\n            repack_info_it->second.callback_members.insert(member_name);\n            thunked_funcptrs["callback_member_" + annotated_member->getQualifiedNameAsString()] =\n              std::pair {context.getCanonicalType(funcptr), no_param_annotations};\n          }\n''')

