# Replace Vulkan's opaque allocator record with mixed generated/manual member
# handling. pUserData is ordinary pointer translation; the five PFN members are
# generated callbacks. The callback argument enums must be registered so host
# callback unpacking can project them.
replace_one(
    'ThunkLibs/libvulkan/libvulkan_interface.cpp',
    '''// TODO: Should not be opaque, but it's usually NULL anyway. Supporting the contained function pointers will need more work.\ntemplate<>\nstruct fex_gen_type<VkAllocationCallbacks> : fexgen::opaque_type {};''',
    '''// Linux Fieldwork research: generate ABI conversion for allocator callback members.\ntemplate<>\nstruct fex_gen_type<VkSystemAllocationScope> {};\ntemplate<>\nstruct fex_gen_type<VkInternalAllocationType> {};\ntemplate<>\nstruct fex_gen_type<VkAllocationCallbacks> {};\ntemplate<>\nstruct fex_gen_config<&VkAllocationCallbacks::pUserData> : fexgen::custom_repack {};\ntemplate<>\nstruct fex_gen_config<&VkAllocationCallbacks::pfnAllocation> : fexgen::callback_member {};\ntemplate<>\nstruct fex_gen_config<&VkAllocationCallbacks::pfnReallocation> : fexgen::callback_member {};\ntemplate<>\nstruct fex_gen_config<&VkAllocationCallbacks::pfnFree> : fexgen::callback_member {};\ntemplate<>\nstruct fex_gen_config<&VkAllocationCallbacks::pfnInternalAllocation> : fexgen::callback_member {};\ntemplate<>\nstruct fex_gen_config<&VkAllocationCallbacks::pfnInternalFree> : fexgen::callback_member {};''')

# Existing custom-member machinery handles the data pointer; callback ABI
# conversion stays generated. Returning true suppresses exit copyback into the
# caller's const VkAllocationCallbacks object.
replace_one(
    'ThunkLibs/libvulkan/Host.cpp',
    '''static void fexfn_impl_libvulkan_Vulkan_SetGuestXDisplayString(uintptr_t GuestTarget, uintptr_t GuestUnpacker) {\n  MakeHostTrampolineForGuestFunctionAt(GuestTarget, GuestUnpacker, &x11_manager.GuestXDisplayString);\n}\n''',
    '''static void fexfn_impl_libvulkan_Vulkan_SetGuestXDisplayString(uintptr_t GuestTarget, uintptr_t GuestUnpacker) {\n  MakeHostTrampolineForGuestFunctionAt(GuestTarget, GuestUnpacker, &x11_manager.GuestXDisplayString);\n}\n\nvoid fex_custom_repack_entry(host_layout<VkAllocationCallbacks>& into, const guest_layout<VkAllocationCallbacks>& from) {\n  into.data.pUserData = const_cast<void*>(from.data.pUserData.force_get_host_pointer());\n}\n\nbool fex_custom_repack_exit(guest_layout<VkAllocationCallbacks>&, const host_layout<VkAllocationCallbacks>&) {\n  return true;\n}\n''')

# The full derived Vulkan sidecar previously had one accessor specialization per
# MAKE_CALLBACK_THUNK entry. callback_member can register sibling fields with
# identical signatures (the two Vulkan internal allocation notifications are a
# concrete example), so deduplicate by canonical emitted signature before
# producing bridge callbacks/accessors.
replace_one(
    'ThunkLibs/Generator/extract_guest_bridge.py',
    '''def clean_prefix(prefix: str) -> str:\n''',
    '''def deduplicate_callbacks(callbacks):\n    unique = []\n    seen = {}\n    for callback in callbacks:\n        index, signature, hash_bytes = callback\n        previous = seen.get(signature)\n        if previous is None:\n            seen[signature] = callback\n            unique.append(callback)\n            continue\n        if previous[2] != hash_bytes:\n            raise RuntimeError(\n                f"Same callback signature emitted with different hashes: {signature}: {previous[2]} vs {hash_bytes}")\n    return unique\n\n\ndef clean_prefix(prefix: str) -> str:\n''')

replace_one(
    'ThunkLibs/Generator/extract_guest_bridge.py',
    '''    callbacks = parse_callbacks(args.guest_inl.read_text())\n    args.bridge_inl.parent.mkdir(parents=True, exist_ok=True)\n''',
    '''    raw_callbacks = parse_callbacks(args.guest_inl.read_text())\n    callbacks = deduplicate_callbacks(raw_callbacks)\n    args.bridge_inl.parent.mkdir(parents=True, exist_ok=True)\n''')

